import type { Parser } from "@lezer/common"
import { highlightTree, tagHighlighter, tags as t } from "@lezer/highlight"

type SyntaxTone = "keyword" | "string" | "number" | "comment" | "function" | "type" | "property" | "tag" | "punctuation"

type CodeToken = { text: string; tone?: SyntaxTone }
type DiffKind = "inserted" | "deleted" | "hunk" | "meta"
type CodeLine = { tokens: CodeToken[]; diff?: DiffKind }

type CodeLanguage = "ts" | "tsx" | "js" | "jsx" | "json" | "css" | "html" | "bash" | "sh" | "md" | "diff" | "plaintext"

const aliases: Record<string, CodeLanguage> = {
  typescript: "ts",
  mts: "ts",
  cts: "ts",
  javascript: "js",
  mjs: "js",
  cjs: "js",
  jsonc: "json",
  json5: "json",
  xml: "html",
  svg: "html",
  shell: "bash",
  zsh: "bash",
  console: "bash",
  terminal: "bash",
  markdown: "md",
  mdx: "md",
  patch: "diff",
  text: "plaintext",
  txt: "plaintext",
  plain: "plaintext",
}

const known = new Set<string>(["ts", "tsx", "js", "jsx", "json", "css", "html", "bash", "sh", "md", "diff"])
const isKnown = (key: string): key is CodeLanguage => known.has(key)

/** Takes a fence's info string or a file extension ("typescript", "zsh"); unknown names give `plaintext`. */
function normalizeLanguage(name?: string): CodeLanguage {
  const key = (name ?? "").trim().split(/\s/)[0]?.toLowerCase() ?? ""
  if (isKnown(key)) return key
  return aliases[key] ?? "plaintext"
}

const tones = new Set<string>([
  "keyword",
  "string",
  "number",
  "comment",
  "function",
  "type",
  "property",
  "tag",
  "punctuation",
])

const isTone = (value: string | undefined): value is SyntaxTone => value !== undefined && tones.has(value)

/** The tone of a token from the classes `syntaxHighlighter` gave it: the first, which is always one of the tones. */
function syntaxToneOf(classes: string): SyntaxTone | undefined {
  const first = classes.split(" ")[0]
  return isTone(first) ? first : undefined
}

const highlighter = tagHighlighter([
  { tag: [t.comment, t.meta, t.documentMeta], class: "comment" },
  { tag: [t.keyword, t.modifier, t.self, t.null, t.bool, t.heading, t.quote], class: "keyword" },
  { tag: [t.string, t.special(t.string), t.regexp, t.character, t.attributeValue, t.url, t.link], class: "string" },
  { tag: [t.number, t.atom, t.unit, t.color, t.literal, t.constant(t.variableName), t.monospace], class: "number" },
  { tag: [t.function(t.variableName), t.function(t.propertyName), t.macroName, t.labelName], class: "function" },
  { tag: [t.typeName, t.className, t.namespace, t.standard(t.variableName)], class: "type" },
  { tag: [t.propertyName, t.attributeName, t.definition(t.propertyName)], class: "property" },
  { tag: [t.tagName, t.angleBracket], class: "tag" },
  { tag: [t.punctuation, t.operator, t.list, t.contentSeparator, t.processingInstruction], class: "punctuation" },
])

const loaders: Partial<Record<CodeLanguage, () => Promise<Parser>>> = {
  ts: () => import("@lezer/javascript").then(({ parser }) => parser.configure({ dialect: "ts" })),
  tsx: () => import("@lezer/javascript").then(({ parser }) => parser.configure({ dialect: "ts jsx" })),
  js: () => import("@lezer/javascript").then(({ parser }) => parser),
  jsx: () => import("@lezer/javascript").then(({ parser }) => parser.configure({ dialect: "jsx" })),
  json: () => import("@lezer/json").then(({ parser }) => parser),
  css: () => import("@lezer/css").then(({ parser }) => parser),
  md: () => import("@lezer/markdown").then(({ parser, GFM }) => parser.configure(GFM)),
  html: async () => {
    const [html, javascript, css] = await Promise.all([
      import("@lezer/html"),
      import("@lezer/javascript"),
      import("@lezer/css"),
    ])
    return html.parser.configure({
      wrap: html.configureNesting([
        { tag: "script", parser: javascript.parser },
        { tag: "style", parser: css.parser },
      ]),
    })
  },
}

const parsers = new Map<CodeLanguage, Parser>()
const loading = new Map<CodeLanguage, Promise<void>>()

/** Undefined while the parser loads, or for a language without one (bash, diff, plaintext). */
function parserFor(language: CodeLanguage) {
  return parsers.get(language)
}

function needsParser(language: CodeLanguage) {
  return Boolean(loaders[language]) && !parsers.has(language)
}

/** Fetches once; every block of that language re-renders highlighted when it resolves. */
function loadParser(language: CodeLanguage) {
  const load = loaders[language]
  if (!load || parsers.has(language)) return Promise.resolve()
  let pending = loading.get(language)
  if (!pending) {
    pending = load().then((parser) => {
      parsers.set(language, parser)
    })
    loading.set(language, pending)
  }
  return pending
}

/** Calls `onLoad` when the parser arrives, unless unsubscribed first. */
function watchParser(language: CodeLanguage, onLoad: () => void) {
  let active = true
  if (needsParser(language))
    loadParser(language).then(
      () => {
        if (active) onLoad()
      },
      () => {},
    )
  return () => {
    active = false
  }
}

function splitLines(tokens: CodeToken[]): CodeLine[] {
  const lines: CodeLine[] = [{ tokens: [] }]
  for (const token of tokens) {
    const parts = token.text.split("\n")
    parts.forEach((part, index) => {
      if (index > 0) lines.push({ tokens: [] })
      if (part) lines.at(-1)!.tokens.push({ text: part, tone: token.tone })
    })
  }
  return lines
}

function parsed(code: string, parser: Parser): CodeToken[] {
  const tokens: CodeToken[] = []
  let position = 0
  highlightTree(parser.parse(code), highlighter, (from, to, classes) => {
    if (from > position) tokens.push({ text: code.slice(position, from) })
    tokens.push({ text: code.slice(from, to), tone: syntaxToneOf(classes) })
    position = to
  })
  if (position < code.length) tokens.push({ text: code.slice(position) })
  return tokens
}

const shellKeywords = new Set(
  "if then else elif fi for in do done case esac while until function return export local readonly set unset".split(
    " ",
  ),
)

const shellPattern =
  /(#.*$)|('[^']*'?|"(?:\\.|[^"\\])*"?)|(\$\{[^}]*\}?|\$\w+)|(\s--?[\w-]+=?)|(&&|\|\||[|;&<>])|(\b\d+\b)|([^\s'"$|;&<>#]+)/g

function shellLine(line: string): CodeToken[] {
  const tokens: CodeToken[] = []
  let position = 0
  let command = true
  for (const match of line.matchAll(shellPattern)) {
    const [text, comment, string, variable, flag, operator, number, word] = match
    if (match.index > position) tokens.push({ text: line.slice(position, match.index) })
    position = match.index + text.length
    if (comment !== undefined && (match.index === 0 || /\s/.test(line[match.index - 1] ?? ""))) {
      tokens.push({ text, tone: "comment" })
    } else if (string !== undefined) tokens.push({ text, tone: "string" })
    else if (variable !== undefined) tokens.push({ text, tone: "property" })
    else if (flag !== undefined) tokens.push({ text, tone: "type" })
    else if (operator !== undefined) {
      tokens.push({ text, tone: "punctuation" })
      command = true
      continue
    } else if (number !== undefined) tokens.push({ text, tone: "number" })
    else if (word !== undefined && shellKeywords.has(word)) {
      tokens.push({ text, tone: "keyword" })
      command = !["in", "export", "local", "readonly"].includes(word)
      continue
    } else if (word !== undefined && command && !word.includes("=")) tokens.push({ text, tone: "function" })
    else tokens.push({ text })
    command = false
  }
  if (position < line.length) tokens.push({ text: line.slice(position) })
  return tokens
}

function diffKind(line: string): DiffKind | undefined {
  if (/^(\+\+\+|---|diff |index )/.test(line)) return "meta"
  if (line.startsWith("@@")) return "hunk"
  if (line.startsWith("+")) return "inserted"
  if (line.startsWith("-")) return "deleted"
  return undefined
}

/** A language whose parser hasn't loaded yet comes back plain; call `loadParser` and highlight again once it resolves. */
function highlight(code: string, language: CodeLanguage, parser = parsers.get(language)): CodeLine[] {
  if (language === "diff") {
    return code.split("\n").map((line) => ({ tokens: line ? [{ text: line }] : [], diff: diffKind(line) }))
  }
  if (language === "bash" || language === "sh") {
    return code.split("\n").map((line) => ({ tokens: shellLine(line) }))
  }
  return splitLines(parser ? parsed(code, parser) : [{ text: code }])
}

export {
  highlight,
  highlighter as syntaxHighlighter,
  loadParser,
  needsParser,
  normalizeLanguage,
  parserFor,
  syntaxToneOf,
  watchParser,
}
export type { CodeLanguage, CodeLine, CodeToken, DiffKind, SyntaxTone }

import { definePrimitive, dispatch, type ChangeDetails } from "@ui-sdk/core"

import { unavailable } from "@/lib/action-refusal"

type CodeBlockCopyDetails = ChangeDetails<"copy">

type CodeBlockOptions = {
  text?: string
  onCopy?: (text: string, details: CodeBlockCopyDetails) => void
}

const COPIED_FOR = 2000

const codeBlock = definePrimitive({
  name: "code-block",
  options: { text: "string", onCopy: "callback" },
  state: (options: CodeBlockOptions) => ({ value: options.text ?? "", copied: false }),
  sync: (options) => ({ value: options.text ?? "" }),
  api: (context) => {
    let timer: ReturnType<typeof setTimeout> | undefined
    context.onDestroy(() => clearTimeout(timer))
    let text = context.options().text
    context.onOptions((options) => {
      if (options.text === text) return
      text = options.text
      clearTimeout(timer)
      context.store.set({ copied: false })
    })
    return {
      /** Where the page has no clipboard access, a press gets `false`. */
      copy(event?: Event) {
        const code = context.options().text ?? ""
        const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard
        if (!clipboard) return unavailable("copy", "isn't available: the page has no clipboard access", { event })
        return clipboard.writeText(code).then(
          () => {
            clearTimeout(timer)
            context.store.set({ copied: true })
            timer = setTimeout(() => context.store.set({ copied: false }), COPIED_FOR)
            dispatch(context, "onCopy", code, { reason: "copy", event })
            return true
          },
          () => unavailable("copy", "was blocked by the browser", { event }),
        )
      },
    }
  },
  slots: (slot) => ({
    root: slot<{}, { copied: boolean }>({
      state: (state) => ({ copied: state.copied }),
      attrs: (state) => ({ role: "group", "data-copied": state.copied ? "" : undefined }),
    }),
  }),
  agent: { actions: ["copy"] },
})

export { codeBlock }
export type { CodeBlockCopyDetails, CodeBlockOptions }

"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import {
  useCallback,
  useMemo,
  useSyncExternalStore,
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
} from "react"
import { CheckIcon, CopyIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { codeBlock, type CodeBlockOptions } from "@/components/ui/code-block-primitive"
import {
  highlight,
  normalizeLanguage,
  parserFor,
  watchParser,
  type CodeLanguage,
  type CodeLine,
  type SyntaxTone,
} from "@/components/ui/code-highlight"
import { ScrollArea, ScrollAreaCorner, ScrollAreaScrollbar, ScrollAreaViewport } from "@/components/ui/scroll-area"
import { cn } from "@/lib/utils"

type CodeBlockLabels = {
  copy: string
  /** Announced, and the button's name, for two seconds after copying. */
  copied: string
  /** The block's name when it has no string `title` or `aria-label`. */
  code: string
}

const defaultLabels: CodeBlockLabels = { copy: "Copy code", copied: "Copied", code: "Code" }

type LineRange = number | readonly [from: number, to: number]

type CodeBlockProps = Omit<ComponentProps<"div">, "children" | "title" | "onCopy"> & {
  code: string
  /** ts, tsx, js, jsx, json, css, html, bash/sh, md, diff or plaintext; aliases like "typescript" work too. */
  language?: CodeLanguage | (string & {})
  /** A filename or caption in a header above the code. */
  title?: ReactNode
  /** Content at the end of the header, before the copy button, like a language badge. */
  actions?: ReactNode
  /** Shows a copy button. Agents can always call the block's `copy` action. */
  copyable?: boolean
  onCopy?: CodeBlockOptions["onCopy"]
  lineNumbers?: boolean
  /** One-based line numbers or inclusive ranges, marked with a fill and a start edge. */
  highlightLines?: readonly LineRange[]
  wrap?: boolean
  /** A CSS length, like "24rem"; the code scrolls inside past it. */
  maxHeight?: string
  labels?: Partial<CodeBlockLabels>
}

const toneClassNames = {
  keyword: "text-syntax-keyword",
  string: "text-syntax-string",
  number: "text-syntax-number",
  comment: "text-syntax-comment italic",
  function: "text-syntax-function",
  type: "text-syntax-type",
  property: "text-syntax-property",
  tag: "text-syntax-tag",
  punctuation: "text-syntax-punctuation",
} satisfies Record<SyntaxTone, string>

function useHighlightedLines(code: string, language: CodeLanguage) {
  const subscribe = useCallback((onLoad: () => void) => watchParser(language, onLoad), [language])
  const current = () => parserFor(language)
  const parser = useSyncExternalStore(subscribe, current, current)
  return useMemo(() => highlight(code, language, parser), [code, language, parser])
}

function lineSet(ranges: readonly LineRange[] | undefined) {
  const lines = new Set<number>()
  for (const range of ranges ?? []) {
    if (typeof range === "number") lines.add(range)
    else for (let line = range[0]; line <= range[1]; line++) lines.add(line)
  }
  return lines
}

function CodeLineView({
  line,
  number,
  highlighted,
  lineNumbers,
}: {
  line: CodeLine
  number: number
  highlighted: boolean
  lineNumbers: boolean
}) {
  return (
    <span
      data-slot="code-line"
      data-highlighted={highlighted ? "" : undefined}
      data-diff={line.diff}
      className="flex border-s-2 border-transparent px-inset-item data-highlighted:border-primary data-highlighted:bg-code-highlight data-[diff=deleted]:bg-destructive-soft data-[diff=deleted]:text-destructive-soft-foreground data-[diff=hunk]:text-syntax-type data-[diff=inserted]:bg-success-soft data-[diff=inserted]:text-success-soft-foreground data-[diff=meta]:text-muted-foreground"
    >
      {lineNumbers && (
        <span
          data-slot="code-line-number"
          aria-hidden="true"
          className="w-(--code-gutter) shrink-0 pe-group text-end text-muted-foreground tabular-nums select-none"
        >
          {number}
        </span>
      )}
      <span data-slot="code-line-content" className="min-w-0 flex-1">
        {line.tokens.length === 0
          ? "\n"
          : line.tokens.map((token, index) =>
              token.tone ? (
                // oxlint-disable-next-line react/no-array-index-key -- tokens of a line have no identity but their order
                <span key={index} className={toneClassNames[token.tone]}>
                  {token.text}
                </span>
              ) : (
                token.text
              ),
            )}
      </span>
    </span>
  )
}

function CodeBlock({
  code,
  language,
  title,
  actions,
  copyable = true,
  onCopy,
  lineNumbers = false,
  highlightLines,
  wrap = false,
  maxHeight,
  labels: labelOverrides,
  className,
  style,
  "aria-label": ariaLabel,
  ...props
}: CodeBlockProps) {
  const labels = { ...defaultLabels, ...labelOverrides }
  const text = code.replace(/\r?\n$/, "")
  const lang = normalizeLanguage(language)
  const lines = useHighlightedLines(text, lang)
  const highlighted = useMemo(() => lineSet(highlightLines), [highlightLines])
  const handle = usePrimitive(codeBlock, { text, onCopy })
  const header = title !== undefined || actions !== undefined
  const scrolls = !wrap || maxHeight !== undefined
  const name = ariaLabel ?? (typeof title === "string" ? title : labels.code)

  const copyButton = (copied: boolean) =>
    copyable && (
      <Button
        variant="ghost"
        size="icon"
        aria-label={copied ? labels.copied : labels.copy}
        data-agent-hidden=""
        className={cn("size-control-sm", !header && "absolute end-inline top-inline z-10 bg-muted")}
        onClick={(event) => handle.api.copy(event.nativeEvent)}
      >
        {copied ? <CheckIcon /> : <CopyIcon />}
      </Button>
    )

  return usePart(
    handle,
    "root",
    {},
    {
      ...({ "data-slot": "code-block", "data-language": lang } as Record<`data-${string}`, string>),
      "aria-label": name,
      style: {
        ...style,
        "--code-gutter": `${String(lines.length).length + 1}ch`,
        ...(maxHeight === undefined ? {} : { "--code-block-max-height": maxHeight }),
      } as CSSProperties,
      className: cn(
        "relative flex min-w-0 flex-col overflow-hidden rounded-surface border bg-muted text-foreground",
        className,
      ),
      ...props,
      children: ({ copied }: { copied: boolean }) => (
        <>
          {header && (
            <div
              data-slot="code-block-header"
              className="flex min-h-control items-center gap-items border-b ps-(--item-padding-x) pe-inline text-caption text-muted-foreground"
            >
              <span className="min-w-0 flex-1 truncate font-mono">{title}</span>
              {actions}
              {copyButton(copied)}
            </div>
          )}
          {!header && copyButton(copied)}
          <ScrollArea className="flex min-h-0 flex-col">
            <ScrollAreaViewport
              tabIndex={scrolls ? 0 : undefined}
              render={(part) => <pre {...part} />}
              className={cn(
                "m-0 h-auto min-h-0 flex-1 py-inset-item font-mono text-caption leading-relaxed",
                maxHeight !== undefined && "max-h-(--code-block-max-height)",
                !header && copyable && "[&_[data-slot=code-line]]:pe-section",
                wrap ? "whitespace-pre-wrap wrap-anywhere" : "whitespace-pre [&_[data-slot=code-line]]:min-w-max",
              )}
            >
              <code data-language={lang} className="grid">
                {lines.map((line, index) => (
                  <CodeLineView
                    // oxlint-disable-next-line react/no-array-index-key -- lines of a code sample have no identity but their order
                    key={index}
                    line={line}
                    number={index + 1}
                    highlighted={highlighted.has(index + 1)}
                    lineNumbers={lineNumbers}
                  />
                ))}
              </code>
            </ScrollAreaViewport>
            <ScrollAreaScrollbar data-agent-hidden="" />
            <ScrollAreaScrollbar orientation="horizontal" data-agent-hidden="" />
            <ScrollAreaCorner />
          </ScrollArea>
          <output className="sr-only">{copied ? labels.copied : ""}</output>
        </>
      ),
    },
    "div",
  )
}

type CodeProps = ComponentProps<"code">

function Code({ className, ...props }: CodeProps) {
  return (
    <code
      data-slot="code"
      className={cn("rounded-sm bg-muted px-inline py-px font-mono break-words", className)}
      {...props}
    />
  )
}

export { Code, CodeBlock }
export { normalizeLanguage }
export type { CodeLanguage, SyntaxTone }
export type { CodeBlockLabels, CodeBlockProps, CodeProps, LineRange }

"use client"

import type { ReactNode } from "react"

import { CodeBlock, type CodeBlockProps } from "@/components/ui/code-block"
import { Tabs, TabsIndicator, TabsList, TabsPanel, TabsTab } from "@/components/ui/tabs"
import { cn } from "@/lib/utils"

type CodeFile = {
  /** The tab's text, usually a filename; also the tab's value unless `value` is set. */
  title: string
  value?: string
  code: string
  language?: CodeBlockProps["language"]
  highlightLines?: CodeBlockProps["highlightLines"]
  icon?: ReactNode
}

type CodeTabsProps = Pick<
  CodeBlockProps,
  "lineNumbers" | "wrap" | "maxHeight" | "copyable" | "onCopy" | "labels" | "className"
> & {
  files: readonly CodeFile[]
  /** Names the tab list, like "Installation files". */
  "aria-label": string
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
}

const valueOf = (file: CodeFile) => file.value ?? file.title

function CodeTabs({
  files,
  "aria-label": label,
  value,
  defaultValue,
  onValueChange,
  className,
  ...block
}: CodeTabsProps) {
  return (
    <Tabs
      render={<div data-slot="code-tabs" />}
      value={value}
      defaultValue={defaultValue ?? (files[0] ? valueOf(files[0]) : undefined)}
      onValueChange={(next) => next !== null && onValueChange?.(next)}
      className={cn("min-w-0 gap-0 overflow-hidden rounded-surface border bg-muted", className)}
    >
      <div className="flex min-w-0 border-b p-inline">
        <TabsList aria-label={label} className="bg-transparent p-0">
          <TabsIndicator />
          {files.map((file) => (
            <TabsTab key={valueOf(file)} value={valueOf(file)} className="font-mono text-caption">
              {file.icon}
              {file.title}
            </TabsTab>
          ))}
        </TabsList>
      </div>
      {files.map((file) => (
        <TabsPanel key={valueOf(file)} value={valueOf(file)} className="rounded-none">
          <CodeBlock
            code={file.code}
            language={file.language}
            highlightLines={file.highlightLines}
            aria-label={file.title}
            className="rounded-none border-0"
            {...block}
          />
        </TabsPanel>
      ))}
    </Tabs>
  )
}

export { CodeTabs }
export type { CodeFile, CodeTabsProps }
